parameters.command:
python3 << 'EOF' > /tmp/build-flow.json
import json

# Load registry responses
ixp_data = json.load(open('/tmp/ixp-invoice-def.json'))
end_data = json.load(open('/tmp/end-def.json'))
script_data = json.load(open('/tmp/script-def.json'))

ixp_node_def = ixp_data['Data']['Node']
end_node_def = end_data['Data']['Node']
script_node_def = script_data['Data']['Node']

# IxP node fields
ixp_defaults = ixp_node_def['inputDefaults']
ixp_model_blob = ixp_defaults['model']
# modelName is not null here ("invoiceixp-cef0d447-ixp"), so use it
# But per impl rule: when null, use modelDisplayName. It's non-null here.
model_name = ixp_model_blob.get('modelName') or ixp_model_blob.get('modelDisplayName')

ixp_output_def = ixp_node_def['outputDefinition']['output']
ixp_error_def = ixp_node_def['outputDefinition']['error']

ixp_type = ixp_node_def['nodeType']
ixp_version = ixp_node_def.get('version', '1.0.0')

flow = {
    "id": "35cafab8-e326-4506-a6b4-2267102f5ade",
    "version": "1.8",
    "name": "Smoke",
    "nodes": [
        {
            "id": "start",
            "type": "core.trigger.manual",
            "typeVersion": "1.0",
            "display": {"label": "Manual trigger"},
            "inputs": {
                "entryPointId": "50623c7d-b90b-4d4c-9393-b640083c5e74",
                "isDefaultEntryPoint": True
            }
        },
        {
            "id": "extractInvoice",
            "type": ixp_type,
            "typeVersion": ixp_version,
            "display": {"label": "Invoice Model"},
            "inputs": {
                "model": ixp_model_blob,
                "modelName": ixp_defaults.get('modelName'),
                "projectName": ixp_defaults.get('projectName'),
                "folderKey": ixp_defaults.get('folderKey'),
                "folderName": ixp_defaults.get('folderName'),
                "versionTag": "",
                "pageRange": "",
                "fileRef": "=js:$vars.start.output.fileRef"
            },
            "outputs": {
                "output": ixp_output_def,
                "error": ixp_error_def
            }
        },
        {
            "id": "logOk",
            "type": "core.action.script",
            "typeVersion": "1.0",
            "display": {"label": "Log OK"},
            "inputs": {
                "script": "const result = $vars.extractInvoice.output;\nreturn { ok: \"ok\" };"
            }
        },
        {
            "id": "end",
            "type": "core.control.end",
            "typeVersion": "1.0",
            "display": {"label": "End"}
        }
    ],
    "edges": [
        {
            "id": "e-start-extract",
            "sourceNodeId": "start",
            "sourceHandle": "output",
            "targetNodeId": "extractInvoice",
            "targetPort": "input"
        },
        {
            "id": "e-extract-script",
            "sourceNodeId": "extractInvoice",
            "sourceHandle": "success",
            "targetNodeId": "logOk",
            "targetPort": "input"
        },
        {
            "id": "e-script-end",
            "sourceNodeId": "logOk",
            "sourceHandle": "success",
            "targetNodeId": "end",
            "targetPort": "input"
        }
    ],
    "definitions": [
        end_node_def,
        script_node_def,
        ixp_node_def,
        {
            "nodeType": "core.trigger.manual",
            "version": "1.0",
            "category": "trigger",
            "description": "Start workflow manually",
            "tags": ["trigger", "start", "manual"],
            "sortOrder": 40,
            "display": {
                "label": "Manual trigger",
                "icon": "play",
                "shape": "circle"
            },
            "handleConfiguration": [
                {
                    "position": "right",
                    "handles": [
                        {
                            "id": "output",
                            "type": "source",
                            "handleType": "output",
                            "showButton": True,
                            "constraints": {"forbiddenTargetCategories": ["trigger"]}
                        }
                    ],
                    "visible": True
                }
            ],
            "model": {
                "type": "bpmn:StartEvent",
